#!/bin/sh

# Backup of the macOS preferences that differ from Apple's defaults on this
# machine, captured on 2026-10-09. Companion to macos/setup.sh: that file
# holds the opinionated set we want on every machine, this one restores the
# choices already made by hand in System Settings.
#
# Generated by macos/backup.sh from macos/keys.list. Edit those, not this file:
# the next backup run overwrites everything below.
#
# Run as your own user, never with sudo. Idempotent; setup.sh runs it.
#
# Trackpad and keyboard keys here are read by the window server at login, so
# those changes land after the next logout, not immediately.

# -------------------------------------------------------------- Appearance
# Dark mode. Removing this key (not setting it to false) restores Light.
defaults write NSGlobalDomain AppleInterfaceStyle -string "Dark"
# Font smoothing threshold: no anti-aliasing at or below this point size.
defaults write NSGlobalDomain AppleAntiAliasingThreshold -int 4
# Double-clicking a title bar zooms instead of minimizing when false.
defaults write NSGlobalDomain AppleMiniaturizeOnDoubleClick -bool false
# Flash the screen on system beep.
defaults write NSGlobalDomain "com.apple.sound.beep.flash" -int 0

# ------------------------------------------------------ Scrolling and keys
# Natural scrolling: content follows the fingers when true.
defaults write NSGlobalDomain "com.apple.swipescrolldirection" -bool false
# Two-finger swipe to go back/forward in pages.
defaults write NSGlobalDomain AppleEnableSwipeNavigateWithScrolls -bool false
# True: F1-F12 are standard function keys and fn gives brightness/volume.
defaults write NSGlobalDomain "com.apple.keyboard.fnState" -bool true
# Force Touch.
defaults write NSGlobalDomain "com.apple.trackpad.forceClick" -bool true
# As-you-type spell checking.
defaults write NSGlobalDomain NSAllowContinuousSpellChecking -bool false

# ---------------------------------------------------------------- Trackpad
# Two domains: AppleMultitouchTrackpad is the built-in trackpad, the Bluetooth
# one is an external Magic Trackpad. The -currentHost keys below are the copies
# the window server actually reads; they apply after the next logout.
# Tap to click.
defaults write com.apple.AppleMultitouchTrackpad Clicking -int 0
# Tap-and-a-half dragging.
defaults write com.apple.AppleMultitouchTrackpad Dragging -int 0
# Tap to click, external trackpad.
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad Clicking -int 0
# Tap-and-a-half dragging, external trackpad.
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad Dragging -int 0
# Two-finger rotate gesture.
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad TrackpadRotate -bool false
# Three-finger window drag.
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad TrackpadThreeFingerDrag -bool false
# Three-finger tap (look up).
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad TrackpadThreeFingerTapGesture -int 0
# Right-edge two-finger swipe for Notification Center (3 = on).
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad TrackpadTwoFingerFromRightEdgeSwipeGesture -int 3
# Rotate gesture, per-machine copy.
defaults -currentHost write NSGlobalDomain "com.apple.trackpad.rotateGesture" -bool false
# Three-finger drag, per-machine copy.
defaults -currentHost write NSGlobalDomain "com.apple.trackpad.threeFingerDragGesture" -bool false
# Three-finger tap, per-machine copy.
defaults -currentHost write NSGlobalDomain "com.apple.trackpad.threeFingerTapGesture" -int 0
# Two-finger right click.
defaults -currentHost write NSGlobalDomain "com.apple.trackpad.enableSecondaryClick" -bool true
# Right-edge swipe, per-machine copy.
defaults -currentHost write NSGlobalDomain "com.apple.trackpad.twoFingerFromRightEdgeSwipeGesture" -int 3
# 2 = momentum scrolling on both axes.
defaults -currentHost write NSGlobalDomain "com.apple.trackpad.scrollBehavior" -int 2

# -------------------------------------------------------------------- Dock
# Dock edge: left, bottom or right.
defaults write com.apple.dock orientation -string "left"
# Icon size in points.
defaults write com.apple.dock tilesize -float 49
# Bottom-right hot corner. 1 off, 2 Mission Control, 3 app windows, 4 Desktop, 5 screen saver, 13 lock screen, 14 Quick Note.
defaults write com.apple.dock wvous-br-corner -int 14

# ------------------------------------------------------------------ Finder
# Recent Tags section in the sidebar.
defaults write com.apple.finder ShowRecentTags -bool false

# ---------------------------------------------------------------- Menu bar
# Date next to the clock: 0 auto, 1 never, 2 always.
defaults write com.apple.menuextra.clock ShowDate -int 2
# AM/PM suffix.
defaults write com.apple.menuextra.clock ShowAMPM -bool true
# Day of the week.
defaults write com.apple.menuextra.clock ShowDayOfWeek -bool false
# Blink the time separators every second.
defaults write com.apple.menuextra.clock FlashDateSeparators -bool true
# Recently-used items kept in Control Center.
defaults write com.apple.controlcenter NumberOfRecents -int 0

# ------------------------------------------------------------------- Restart
# None here: setup.sh runs this file before macos/setup.sh, which restarts
# Finder, Dock and SystemUIServer once at the end. Running this file on its own
# needs that by hand: killall Finder Dock SystemUIServer

printf '    ok    macOS non-default prefs written\n'
